// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // c.withdraw sends via transfer to msg.sender (the owner = this test contract);
    // a payable receive() lets the 2300-gas transfer succeed.
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 balance, uint256 value) public {
        balance = bound(balance, 1, 1 ether);
        vm.deal(address(c), balance);
        vm.assume(value < balance);
        vm.assume(value > 0);

        uint256 before = address(c).balance;
        c.withdraw(value);

        assertTrue(address(c).balance == before - value);
    }
}
